create table if not exists "__DbMaintenanceHistory" ("Version" varchar(64) primary key, "AppliedAt" timestamptz not null, "Checksum" varchar(128) not null);
create table if not exists "Corporate" ("Id" bigint generated by default as identity primary key, "Name" varchar(256) not null default '', "Description" text not null default '', "Code" varchar(128) not null default '', "Platform" integer not null default 0, "CreateTime" bigint not null default 0, "UpdateTime" bigint null, "DeleteFlag" boolean not null default false);
create table if not exists "User" ("Id" bigint generated by default as identity primary key, "CreateTime" bigint not null default 0, "Name" varchar(256) not null default '', "Email" varchar(256) not null default '', "Phone" varchar(64) not null default '', "Password" text not null default '', "Platform" integer not null default 0, "Disabled" boolean not null default false, "Avatar" text null, "UserType" varchar(64) null, "Crops" jsonb not null default '[]'::jsonb);
create table if not exists "Employee" ("Id" bigint generated by default as identity primary key, "CorpId" bigint not null, "UserId" bigint not null, "UserName" varchar(256) not null default '', "Code" varchar(128) not null default '', "EmpName" varchar(256) not null default '', "WorkPhone" varchar(64) not null default '', "WorkEmail" varchar(256) not null default '', "Status" integer not null default 0, "IsDummy" boolean not null default false, "Invite" varchar(256) null, "UserBound" boolean not null default false, "EmployeeGroups" jsonb not null default '[]'::jsonb, "Depts" jsonb not null default '[]'::jsonb, "DeptId" bigint null, "HeriarchyId" text not null default '', "CreateTime" bigint not null default 0, "UpdateTime" bigint null, "DeleteFlag" boolean not null default false);
create table if not exists "Department" ("Id" bigint generated by default as identity primary key, "CorpId" bigint not null, "Code" varchar(128) not null default '', "Name" varchar(256) not null default '', "IsCompany" boolean not null default false, "ParentId" bigint null, "ParentName" varchar(256) not null default '', "HeriarchyId" text not null default '', "HeriarchyName" text not null default '', "CreateTime" bigint not null default 0, "UpdateTime" bigint null, "DeleteFlag" boolean not null default false);
create table if not exists "EmployeeDepartment" ("Id" bigint generated by default as identity primary key, "CorpId" bigint not null, "EmployeeId" bigint not null, "DepartmentId" bigint not null, "IsManager" boolean not null default false, "SortValue" integer not null default 0, "CreateTime" bigint not null default 0, "UpdateTime" bigint null, "DeleteFlag" boolean not null default false);
create table if not exists "FormDef" ("Id" bigint generated by default as identity primary key, "CorpId" bigint not null, "AppId" bigint not null, "TemplateId" varchar(128) null, "Name" varchar(256) not null default '', "Content" jsonb not null default '{}'::jsonb, "UsingWorkflow" boolean not null default false, "FormSettings" jsonb not null default '{}'::jsonb, "PublicRelatedFormIds" jsonb not null default '[]'::jsonb, "CreateTime" bigint not null default 0, "UpdateTime" bigint null, "DeleteFlag" boolean not null default false);
create table if not exists "FormData" ("Id" bigint generated by default as identity primary key, "CorpId" bigint not null, "AppId" bigint not null, "FormId" bigint not null, "FlowStatus" integer not null default 0, "Data" jsonb not null default '{}'::jsonb, "CreateTime" bigint not null default 0, "UpdateTime" bigint null, "DeleteFlag" boolean not null default false);
create table if not exists "UserCorp" ("Id" bigint generated by default as identity primary key, "UserId" bigint not null, "CorpId" bigint null, "IsCorpOwner" boolean not null default false, "CorpType" varchar(64) not null default '', "IsDefault" boolean not null default false);
